  "📒 任務本、🧹 假日活動、🐔 小肥雞來了！": "📒 Книга заданий, 🧹 события выходных и 🐔 цыплята!",
  "任務本": "Книга заданий",
  "上方「📒 任務」：每天 3 題、每週 5 題，集章換臉妝，還有獎盃和獎盃展示牆": "«📒 Задания» вверху: 3 в день и 5 в неделю, штампы на макияж, кубки и стена кубков",
  "假日活動": "События выходных",
  "週六、週日 10:00～18:00 全營地一起完成目標，拿主題獎盃和小家具。今天開到晚上 10 點：營地大掃除！": "По субботам и воскресеньям 10:00–18:00 весь лагерь идёт к общей цели — кубки и мебель. Сегодня до 22:00: большая уборка!",
  "🎉 假日活動是什麼？": "🎉 Что такое события выходных?",
  "週六、週日 10:00～18:00 有主題活動（大掃除、雞蛋節、釣魚大會、料理日⋯四週輪一次）。全營地一起達到目標，有參加的人都拿主題獎盃；自己的 3 題做完送小家具。每到整點 5 分鐘內做的算 2 倍。": "По субботам и воскресеньям 10:00–18:00 — тематическое событие (уборка, яичный праздник, рыболовный турнир, день готовки… по кругу раз в четыре недели). Когда лагерь достигнет цели, все участники получат кубок; за свои 3 задания — маленькую мебель. Первые 5 минут каждого часа — всё в двойном зачёте.",
  "會用掉採集籃的 {icon}{name} ×1（你有 {n} 個）。一次 1 隻小鴨跟著你走 3 分鐘，一天最多餵 3 次": "Потратится {icon}{name} ×1 из корзины (у тебя {n}). Один утёнок ходит за тобой 3 минуты; кормить можно до 3 раз в день",
  "🦆 要餵小鴨嗎？": "🦆 Покормить утёнка?",
  "會用掉採集籃的 {icon}{name} ×1（你有 {n} 個），小鴨跟著你走 3 分鐘": "Потратится {icon}{name} ×1 из корзины (у тебя {n}); утёнок будет ходить за тобой 3 минуты",
  "🦆 餵牠": "🦆 Покормить",
