  "下一場：{m}/{d} {h}:00 {icon} {name}": "Следующее: {d}.{m} в {h}:00 {icon} {name}",
  "週六、週日 10:00～18:00 有全營地一起完成的主題活動，做完拿主題獎盃和小家具。": "По субботам и воскресеньям 10:00–18:00 — тематическое событие для всего лагеря: кубки и маленькая мебель.",
  "還有 {h} 小時 {m} 分": "Осталось {h} ч {m} мин",
  "⏰ 整點小高潮中！": "⏰ Часовой бонус!",
  "3 題都做完": "Все 3 задания",
  "全營地達到 {n}：有參加的人都拿 {name}": "Лагерь наберёт {n}: всем участникам — {name}",
  "中間每達到一段，有參加的人 +{g} 🌰": "За каждый этап все участники получают +{g} 🌰",
  "🎉 今天是「{icon} {name}」！點上方「📒 任務 → 🎉 假日」看看大家的進度": "🎉 Сегодня «{icon} {name}»! Нажми «📒 Задания → 🎉 Выходные», чтобы увидеть прогресс",
  "🏆 全營地一起達到 {n} 了！有參加的人都拿到「{name}」": "🏆 Лагерь набрал {n}! Все участники получили «{name}»",
  "🎉 全營地一起達到 {n}！有參加的人 +{g} 🌰": "🎉 Лагерь набрал {n}! Участникам +{g} 🌰",
  "🌟 {name} 找到大金蛋了！": "🌟 {name} нашёл большое золотое яйцо!",
  "🌟 這附近藏了一顆大金蛋！先找到的 +20 🌰": "🌟 Рядом спрятано большое золотое яйцо! Первому +20 🌰",
  "🌟 找到大金蛋了！+{g} 🌰": "🌟 Нашёл большое золотое яйцо! +{g} 🌰",
  "🥚 找到一顆彩蛋！": "🥚 Нашёл расписное яйцо!",
  "<kbd>E</kbd> 🥚 撿起彩蛋": "<kbd>E</kbd> 🥚 Поднять яйцо",
  "⏳ {t} 後可以再餵": "⏳ Снова покормить через {t}",
  "餵牠就會下蛋 🥚": "Покорми — и будет яйцо 🥚",
  "餵一次蔬菜或果實，1 小時後就下一顆蛋（沒餵不會下蛋）。每隻一天 3 次、每次要隔 1 小時。越餵越圓，3 級的一次下 2 顆，偶爾還會下金蛋！": "Дай овощ или фрукт — через час будет яйцо (без еды яиц нет). Каждого цыплёнка можно кормить 3 раза в день с перерывом в час. Чем больше кормишь, тем он круглее: на 3 уровне — по 2 яйца, иногда золотое!",
  "牠還飽飽的，{t} 後再餵": "Ещё сыт — покорми через {t}",
  "🐔 吃得好開心 💕・1 小時後下蛋": "🐔 Вкусно! 💕 · Яйцо через час",
  "餵一次蔬菜或果實，1 小時後下一顆蛋；沒餵不會下蛋": "Покормил овощем или фруктом — через час яйцо; без еды яиц нет",
  "每隻一天餵 3 次，每次要隔 1 小時；餵越多越圓，3 級的一次下 2 顆": "Каждого — 3 раза в день с перерывом в час; чем больше кормишь, тем круглее, на 3 уровне по 2 яйца",
  "蛋最多存 6 顆，偶爾有金蛋": "Копится до 6 яиц; иногда золотое",
  "菜園旁邊蓋一圈小圍籬，養胖胖的小雞：餵一次下一顆蛋（每天 3 次），餵越多越圓；雞蛋可以煮番茄炒蛋、玉子燒、布丁⋯": "Загончик у огорода с пухлыми цыплятами: одно кормление — одно яйцо (3 раза в день), чем больше кормишь, тем круглее; из яиц — яичница с томатами, тамагояки, пудинг…",
  "🍀 釣魚好運料理和營火，可以一起加嗎？": "🍀 Суммируются ли «удачные» блюда и костёр?",
  "不會加在一起，算比較高的那個。「釣魚好運」料理：稀有魚 ×1.5～×2；在營火河畔火很旺 ×1.3、超旺 ×1.6。例如吃了 ×2 的料理，火再旺也是 ×2。": "Не суммируются — действует большее. Блюда «удачной рыбалки»: редкие рыбы ×1,5–×2; у реки при сильном костре ×1,3, при очень сильном ×1,6. Например, с блюдом ×2 будет ×2, как бы ни горел костёр.",
  "👉 帶我去營火河畔": "👉 К реке у костра",
  "📒 任務本怎麼玩？": "📒 Как работает книга заданий?",
  "點上方「📒 任務」。每天 3 題（每題 +5 🌰，做完 3 題送當天造型＋1 個章，每天可以換 1 題）；每週 5 題（做完 3 題送小盆栽、5 題送本週造型和銀獎盃）。一個月集滿 20 個章送 1 款臉妝和金獎盃。": "Нажми «📒 Задания» вверху. 3 задания в день (по +5 🌰; за все 3 — образ дня и 1 штамп; одно можно заменить). 5 заданий в неделю (за 3 — цветочек, за 5 — образ недели и серебряный кубок). 20 штампов за месяц — макияж и золотой кубок.",
  "👉 打開任務本": "👉 Открыть задания",
