  "贊助限定：那個月贊助就送一頂": "Для спонсоров: дарится тем, кто поддержал в том месяце",
  "在「🏪 小舖 → 🎫 月票」可以買。每天多拿松果、可以買月票家具；不會自動續扣，不買也能玩。": "Покупается в «🏪 Лавка → 🎫 Абонемент». Больше шишек каждый день и мебель для абонемента; без автопродления, играть можно и без него.",
  "每週限定：做完任務本這週的 5 題就拿到；朋友透過你的連結來玩也能拿": "Недельный эксклюзив: выполни 5 недельных заданий — или пусть друг зайдёт по твоей ссылке",
