  "釣到一條船釣限定魚": "Поймай рыбу, что ловится только с лодки",
  "煮 3 道不同的料理": "Приготовь 3 разных блюда",
  "採集 40 次": "Собери 40 раз",
  "圖鑑多收集 3 樣新東西": "Добавь 3 новых записи в справочник",
  "在迷霧森林採到 ★3 稀有的東西": "Найди редкость ★3 в Туманном лесу",
