  "每個人身邊都有一顆小光點，玩遊戲會長大；上方「✨ 小精靈」可以餵它、取名字、孵新的": "У каждого есть огонёк, который растёт, пока ты играешь. Через «✨ Дух» вверху его можно кормить, назвать или вывести нового",
