  "📌 獎勵都是系統照上面的規則自動發的：沒有符合條件就不會拿到，作者不另外補發。邀請前請先跟朋友確認好": "📌 Награды выдаются автоматически по правилам выше: если условия не выполнены, награды нет, и автор не может отправить её повторно. Уточни у друга, прежде чем звать",
  "❌ 不算的情況：自己點自己的連結、只傳圖片沒掃 QR、朋友以前就來過（不算「新朋友」，但每日造型、營火之約還是算）": "❌ Не считается: нажать свою же ссылку, отправить только картинку без сканирования QR или друг, который уже был в игре (не «новый друг», но для наряда дня и свидания у костра считается)",
  "⏳ 朋友中途跳出去沒關係，30 分鐘內回來還是算；時間到之前關掉、30 分鐘內沒回來就不算": "⏳ Ничего страшного, если друг отойдёт — считается, если вернётся в течение 30 мин; если закрыл(а) раньше и не вернулся(лась) за 30 мин — не считается",
  "🏢 <b>同一個網路</b>（同事、家人用同一個 Wi‑Fi）：朋友要待 {m} 分鐘，而且要玩一下（釣魚、採集、撿垃圾、做任務都可以），同一個網路每天最多算 {n} 位": "🏢 <b>Одна сеть</b> (коллеги или семья на одном Wi‑Fi): другу нужно пробыть {m} мин и по-настоящему играть (рыбачить, собирать, убирать мусор или делать задание); до {n} друзей на сеть в день",
  "🔥 <b>營火之約</b>：早上、晚上 9:30～10:00 營火時間，朋友點你的連結進來待滿 {m} 分鐘，兩個人都拿限定造型（依序：營火圍巾 → 烤棉花糖帽 → 流星燈背架），同一對朋友每天算一次": "🔥 <b>Свидание у костра</b>: во время костра (9:30–10:00 утром/вечером) друг заходит по твоей ссылке и остаётся {m} мин — вы оба получаете особый наряд (по порядку: шарф-уголёк → шапка-маршмеллоу → рюкзак-фонарь метеора); раз в день для каждой пары",
  "👒 <b>每日造型</b>：任何朋友（新朋友、老朋友都算）點你的連結進來玩 {m} 分鐘；或自己完成「今日挑戰」3 題": "👒 <b>Наряд дня</b>: любой друг (новый или вернувшийся) играет {m} мин по твоей ссылке — или выполни 3 «Задания дня» сам(а)",
  "👫 <b>新朋友</b>：第一次來營地、點你的連結（或掃 QR 邀請圖）進來，待滿 {m} 分鐘 → 你拿 {g} 顆松果＋這週限定造型；累積 1、3、5 位送禮物家具": "👫 <b>Новые друзья</b>: первый визит по твоей ссылке (или QR) и {m} мин в игре → ты получаешь {g} шишек + наряд недели; мебель в подарок за 1, 3 и 5 друзей",
