  "發光的浮標整個沉下去時，快按 <b>F</b> 拉竿！（只點一下是魚在試探，先別拉）": "Когда светящийся поплавок полностью утонет, жми <b>F</b>, чтобы подсечь! (Лёгкое подрагивание — это поклёвка, жди)",
