  "從營火旁的「🍄 迷霧森林」走進去，走到發光的蘑菇、果實、野花旁邊就會自動採。第一次採到新的種類送松果（★ 越多送越多），全部 {n} 種收集完再送 {b} 顆 🌰": "От костра иди в 🍄 Туманный лес. Подойди к светящимся грибам, ягодам или цветам — они соберутся сами. Каждый новый вид даёт шишки (больше ★ — больше шишек); собери все {n} — ещё {b} 🌰",
