  "想動就去釣魚、疊石頭；想靜就在火邊坐著。每晚 7 點～11 點，每半小時一場小活動 🎣": "Хочется движения? Порыбачь или сложи камни. Хочется тишины? Просто посиди у костра. Мини-события каждые 30 минут с 19 до 23 ч 🎣",
  "🍄 迷霧森林：地上有發光圈圈的蘑菇、果實、野花，走過去按 E 採摘；空中飛的蟲蟲要用捕蟲網（{p} 🌰）按 E 捕。🐚 湖畔碼頭的岸邊可以撿石頭和貝殼。✨ 晚上 8～10 點營火附近偶爾會有寶藏。第一次找到新的種類送松果，全部收集完再送 {b} 顆 🌰": "🍄 Туманный лес: подойди к грибам, ягодам и цветам со светящимся кольцом и нажми E, чтобы собрать; летающих жуков лови сачком ({p} 🌰). 🐚 На берегу озера собирай камни и ракушки. ✨ С 20 до 22 ч у костра иногда появляются сокровища. Новые находки дают шишки; собери атлас — ещё {b} 🌰",
