  "松果不夠，還差 {n} 顆 🌰": "Не хватает шишек — нужно ещё {n} 🌰",
  "🦋 捕蟲網": "🦋 Сачок",
  "空中飛的蟲蟲要用捕蟲網才捕得到。買一支之後一直都能用：白天有瓢蟲、金龜子、螳螂⋯，晚上有螢火蟲、獨角仙、月光蛾⋯": "Для летающих жуков нужен сачок. Покупается один раз навсегда: днём — божьи коровки, бронзовки и богомолы; ночью — светлячки, жуки-носороги и лунные бабочки…",
  "🦋 買一支捕蟲網 🌰 {p}": "🦋 Купить сачок 🌰 {p}",
  "第一個捐的人": "Первый даритель",
  "🎁 捐出": "🎁 Подарить музею",
  "還沒有人捐": "Ещё не подарено",
  "🏛️ 營地標本櫃 {n}／{total}": "🏛️ Музей лагеря {n}/{total}",
  "大家一起把採集到的東西捐進標本櫃，每一格都會寫上「第一個捐的人」的名字。捐出一個送松果（★ 越多送越多）。": "Все вместе наполняют музей — на каждой ячейке имя того, кто подарил первым. За подарки дают шишки (больше ★ — больше шишек).",
  "🏛️ 捐進標本櫃了！你的名字會留在這一格 +{n} 🌰": "🏛️ Подарено! Твоё имя останется на этой ячейке +{n} 🌰",
  "剛好有人先捐了：{name}": "Тебя опередили: {name}",
  "連上伺服器才能看標本櫃": "Подключись к серверу, чтобы увидеть музей",
  "🏛️ {name} 把{icon} {item}捐進了標本櫃": "🏛️ {name} подарил(а) музею {icon} {item}",
  "🔨 手作": "🔨 Поделки",
  "🔨 手作家具": "🔨 Мебель своими руками",
  "做一個": "Сделать",
  "用採集籃裡的東西做家具，做好會放進帳篷背包，回帳篷按「🛠️ 布置」擺出來。「任意」的材料會先用數量多、常見的，★★★ 稀有的不會被拿去用。": "Делай мебель из того, что в корзинке. Она попадает в инвентарь палатки — ставь через 🛠️ Обустройство. «Любые» материалы сначала берутся из самых многочисленных обычных; редкие ★★★ не тратятся никогда.",
  "🔨 做好了：{icon} {name}！放進帳篷背包了": "🔨 Сделано: {icon} {name}! Уже в инвентаре палатки",
  "材料不夠喔": "Не хватает материалов",
