  "🔥 在料理鍋旁邊，可以開始煮了！": "🔥 Ты у котелка — можно готовить!",
  "到中央營火旁的「🍲 營火料理」鍋子才能煮。蔬菜在帳篷前的小菜園種。": "Готовь в 🍲 котелке у центрального костра. Овощи выращивай на огороде перед палаткой.",
  "🍱 我的料理": "🍱 Мои блюда",
  "📖 食譜（第一次煮出新料理送松果）": "📖 Рецепты (первое приготовление блюда даёт шишки)",
