  "🍲 {name} 煮了一道{icon} {dish}": "🍲 {name} приготовил(а) {icon} {dish}",
  "🎁 {name} 送你一份{icon} {dish}！到「📖 圖鑑 → 🍲 料理」可以吃": "🎁 {name} угостил(а) тебя {icon} {dish}! Съешь в 📖 Атлас → 🍲 Готовка",
