  "🥕 {name} 的小菜園": "🥕 Огород {name}",
  "種子免費，種下去等幾小時就能收成，放著不收也不會枯掉。朋友路過可以幫忙澆水，少等 30 分鐘、收成多一個。收成的蔬菜可以拿去營火旁煮料理，或當手作家具的材料。": "Семена бесплатные. Собирай через несколько часов — урожай не вянет. Друзья могут полить: на 30 мин быстрее и +1 к урожаю. Овощи можно приготовить у костра или пустить на поделки.",
  "幫朋友的菜澆水，可以少等 30 分鐘、收成多一個 💧": "Полей грядку друга — на 30 мин быстрее и +1 к урожаю 💧",
