  "湖邊沒有營火，走到水邊按 F 釣魚吧 🎣　岸邊發光的石頭、貝殼可以按 E 撿起來": "Здесь нет костра — иди к воде и нажми F, чтобы рыбачить 🎣  Нажми E, чтобы подбирать светящиеся камни и ракушки на берегу",
