  "地上有發光圈圈的蘑菇、果實、野花，走過去按 E 採摘；空中飛的蟲蟲用捕蟲網按 E 捕 🦋": "Грибы, ягоды и цветы со светящимся кольцом собираются на E; летающих жуков лови сачком и E 🦋",
