  "湖邊": "Берег озера",
  "營地路邊": "Тропинки лагеря",
  "營火區": "Костёр",
  "湖裡釣魚、湖邊、帳篷營地的路邊、中央營火區，偶爾會出現垃圾，走過去按 E 撿起來。撿到的垃圾拿去營火旁的「♻️ 回收桶」丟，每件換 1 顆松果（每天最多 {cap} 顆）。全部收集完送「淨灘小隊領巾」♻️": "Мусор иногда попадается на рыбалке, на берегу озера, на тропинках лагеря и возле костра — подойди и нажми E. Отнеси его в ♻️ бак для переработки у костра — по 1 шишке за штуку (до {cap} в день). Собери атлас — получишь бандану Отряда чистоты ♻️",
