  "🔥 名字前面的小營火徽章，大家都看得到": "🔥 Значок костерка перед именем, его видят все",
  "⛺ 月票限定帳篷花色「營火之夜」（買過就一直留著）": "⛺ Особый узор палатки «Ночь у костра» для пропуска (остаётся у тебя)",
